import{_ as t,c as n,o as i,a2 as a}from"./chunks/framework.PGES7OoM.js";const f=JSON.parse('{"title":"Introduction to config","description":"Understand CurvyConfig, runtime defaults, ambient state, and lifecycle.","frontmatter":{"title":"Introduction to config","description":"Understand CurvyConfig, runtime defaults, ambient state, and lifecycle.","rawMarkdown":"---\\ntitle: Introduction to config\\ndescription: Understand CurvyConfig, runtime defaults, ambient state, and lifecycle.\\n---\\n\\n# Introduction to config\\n\\nA `CurvyConfig` is the runtime context used by Curvy actions. It owns service clients, storage, reactive account and network state, proving, note synchronization, and lifecycle resources.\\n\\n## Choose a constructor\\n\\n| Constructor | Use it for | Defaults |\\n| --- | --- | --- |\\n| [`createBrowserCurvyConfig`](/sdk/config/createBrowserCurvyConfig) | Browser applications | IndexedDB, session restoration, ambient config |\\n| [`createServerCurvyConfig`](/sdk/config/createServerCurvyConfig) | Servers and multi-tenant processes | In-memory storage, no keystore, no ambient config |\\n| [`createCurvyConfig`](/sdk/config/createCurvyConfig) | Custom runtimes and tests | Explicit control over every adapter |\\n\\n## Explicit config\\n\\nPass `config` to actions in tests, servers, and applications that can host more than one Curvy instance.\\n\\n```ts\\nconst balances = await getBalances({ config });\\n```\\n\\nThis makes ownership and lifecycle unambiguous and prevents one request from reading another request\'s ambient state.\\n\\n## Ambient config\\n\\nBrowser constructors register the new config as the ambient default. A single-instance browser application may omit it from subsequent calls.\\n\\n```ts\\nawait createBrowserCurvyConfig();\\nconst balances = await getBalances();\\n```\\n\\nPrefer explicit config in shared libraries even when the host application uses the ambient form.\\n\\n## State and subscriptions\\n\\n`config.state` is the current serializable snapshot. `config.subscribe` observes changes without coupling the SDK to a UI framework. Higher-level event actions such as [`on`](/sdk/actions/events/on) are useful for lifecycle events.\\n\\n## Lifecycle\\n\\nAlways call [`destroyConfig`](/sdk/config/destroyConfig) when a config\'s owner is finished with it.\\n\\n```ts\\nawait config.destroy();\\n```\\n\\nCreating a replacement ambient config does not destroy the previous one automatically.\\n\\n## Reading config state\\n\\n- [`getCurvyConfig`](/sdk/config/getCurvyConfig) reads the ambient config and throws when none exists.\\n- [`peekCurvyConfig`](/sdk/config/peekCurvyConfig) performs the same read without throwing.\\n- [`getActiveNetworks`](/sdk/config/getActiveNetworks), [`getEnvironment`](/sdk/config/getEnvironment), and [`getProtocol`](/sdk/config/getProtocol) read commonly needed config state.\\n- [`getDefaultAggregatorNetwork`](/sdk/config/getDefaultAggregatorNetwork) returns the network funds are shielded on when a deposit lands on a chain without its own aggregator.\\n- [`acceptsPortalShield`](/sdk/config/acceptsPortalShield) tells whether portal deposits can be shielded on a network.\\n- [`setCurvyConfig`](/sdk/config/setCurvyConfig) replaces or clears the ambient config; it does not destroy the previous value.\\n","rawMarkdownPath":"/_raw/sdk/config/index.md","rawMarkdownTitle":"Introduction to config","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/config/index.md"},"headers":[],"relativePath":"sdk/config/index.md","filePath":"sdk/config/index.md","lastUpdated":1790004279000}'),s={name:"sdk/config/index.md"};function o(r,e,c,d,l,h){return i(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="introduction-to-config" tabindex="-1">Introduction to config <a class="header-anchor" href="#introduction-to-config" aria-label="Permalink to &quot;Introduction to config&quot;">​</a></h1><p>A <code>CurvyConfig</code> is the runtime context used by Curvy actions. It owns service clients, storage, reactive account and network state, proving, note synchronization, and lifecycle resources.</p><h2 id="choose-a-constructor" tabindex="-1">Choose a constructor <a class="header-anchor" href="#choose-a-constructor" aria-label="Permalink to &quot;Choose a constructor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Constructor</th><th>Use it for</th><th>Defaults</th></tr></thead><tbody><tr><td><a href="/sdk/config/createBrowserCurvyConfig.html"><code>createBrowserCurvyConfig</code></a></td><td>Browser applications</td><td>IndexedDB, session restoration, ambient config</td></tr><tr><td><a href="/sdk/config/createServerCurvyConfig.html"><code>createServerCurvyConfig</code></a></td><td>Servers and multi-tenant processes</td><td>In-memory storage, no keystore, no ambient config</td></tr><tr><td><a href="/sdk/config/createCurvyConfig.html"><code>createCurvyConfig</code></a></td><td>Custom runtimes and tests</td><td>Explicit control over every adapter</td></tr></tbody></table><h2 id="explicit-config" tabindex="-1">Explicit config <a class="header-anchor" href="#explicit-config" aria-label="Permalink to &quot;Explicit config&quot;">​</a></h2><p>Pass <code>config</code> to actions in tests, servers, and applications that can host more than one Curvy instance.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> balances</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getBalances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ config });</span></span></code></pre></div><p>This makes ownership and lifecycle unambiguous and prevents one request from reading another request&#39;s ambient state.</p><h2 id="ambient-config" tabindex="-1">Ambient config <a class="header-anchor" href="#ambient-config" aria-label="Permalink to &quot;Ambient config&quot;">​</a></h2><p>Browser constructors register the new config as the ambient default. A single-instance browser application may omit it from subsequent calls.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createBrowserCurvyConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> balances</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getBalances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Prefer explicit config in shared libraries even when the host application uses the ambient form.</p><h2 id="state-and-subscriptions" tabindex="-1">State and subscriptions <a class="header-anchor" href="#state-and-subscriptions" aria-label="Permalink to &quot;State and subscriptions&quot;">​</a></h2><p><code>config.state</code> is the current serializable snapshot. <code>config.subscribe</code> observes changes without coupling the SDK to a UI framework. Higher-level event actions such as <a href="/sdk/actions/events/on.html"><code>on</code></a> are useful for lifecycle events.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>Always call <a href="/sdk/config/destroyConfig.html"><code>destroyConfig</code></a> when a config&#39;s owner is finished with it.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">destroy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Creating a replacement ambient config does not destroy the previous one automatically.</p><h2 id="reading-config-state" tabindex="-1">Reading config state <a class="header-anchor" href="#reading-config-state" aria-label="Permalink to &quot;Reading config state&quot;">​</a></h2><ul><li><a href="/sdk/config/getCurvyConfig.html"><code>getCurvyConfig</code></a> reads the ambient config and throws when none exists.</li><li><a href="/sdk/config/peekCurvyConfig.html"><code>peekCurvyConfig</code></a> performs the same read without throwing.</li><li><a href="/sdk/config/getActiveNetworks.html"><code>getActiveNetworks</code></a>, <a href="/sdk/config/getEnvironment.html"><code>getEnvironment</code></a>, and <a href="/sdk/config/getProtocol.html"><code>getProtocol</code></a> read commonly needed config state.</li><li><a href="/sdk/config/getDefaultAggregatorNetwork.html"><code>getDefaultAggregatorNetwork</code></a> returns the network funds are shielded on when a deposit lands on a chain without its own aggregator.</li><li><a href="/sdk/config/acceptsPortalShield.html"><code>acceptsPortalShield</code></a> tells whether portal deposits can be shielded on a network.</li><li><a href="/sdk/config/setCurvyConfig.html"><code>setCurvyConfig</code></a> replaces or clears the ambient config; it does not destroy the previous value.</li></ul>`,20)])])}const p=t(s,[["render",o]]);export{f as __pageData,p as default};
